  const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState('');
  const [records, setRecords] = useState<PurchaseRecord[]>([]); const [summary, setSummary] = useState<SummaryData | null>(null); const [dashboard, setDashboard] = useState<DashboardData | null>(null);
  const [options, setOptions] = useState({ parties: [] as string[], materials: [] as string[], paymentTypes: [] as string[] }); const [selectedParty, setSelectedParty] = useState(''); const [ledger, setLedger] = useState<PurchaseRecord[]>([]); const [ledgerLoading, setLedgerLoading] = useState(false); const [exporting, setExporting] = useState<'party' | 'all' | null>(null);
  const loadData = async (showLoader = true) => { if (showLoader) setLoading(true); setError(''); try { const r = await api.bootstrap(); setRecords(r.records); setSummary(r.summary); setDashboard(r.dashboard); setOptions(r.options); setSelectedParty((x) => x || r.options.parties[0] || ''); } catch (e) { setError(e instanceof Error ? e.message : 'Could not load Google Sheet data.'); } finally { if (showLoader) setLoading(false); } };
  useEffect(() => { loadData(); }, []);
  useEffect(() => { AsyncStorage.getItem(THEME_STORAGE_KEY).then((saved) => { if (saved === 'light' || saved === 'dark') setThemeMode(saved); }).catch(() => {}); }, []);
  useEffect(() => { if (!selectedParty) { setLedger([]); return; } let active = true; setLedgerLoading(true); api.getLedger(selectedParty).then((rows) => { if (active) setLedger(rows); }).catch(() => { if (active) setLedger([]); }).finally(() => { if (active) setLedgerLoading(false); }); return () => { active = false; }; }, [selectedParty]);
  const saveRecord = async (record: PurchaseRecord, values: PurchaseRecord['values']): Promise<boolean> => { if (!String(values.date || '').trim()) { Alert.alert('Date required', 'Please enter a date.'); return false; } if (!String(values.party || '').trim()) { Alert.alert('Party name required', 'Please select or add a party name.'); return false; } setSaving(true); try { const result = await api.savePurchase(record.sheetRow, values) as { sheetRow?: number }; await loadData(false); Alert.alert('Saved', `${record.sheetRow === 0 ? 'Purchase added' : 'Purchase updated'} in Google Sheets, row ${result.sheetRow || record.sheetRow}.`); return true; } catch (e) { Alert.alert('Could not save', e instanceof Error ? e.message : 'Please try again.'); return false; } finally { setSaving(false); } };
  const addOption = async (kind: 'party' | 'material' | 'paymentType', value: string) => { const clean = value.trim(); if (!clean) return; try { await api.addOption(kind, clean); setOptions((old) => ({ parties: kind === 'party' && !old.parties.includes(clean) ? [...old.parties, clean] : old.parties, materials: kind === 'material' && !old.materials.includes(clean) ? [...old.materials, clean] : old.materials, paymentTypes: kind === 'paymentType' && !old.paymentTypes.includes(clean) ? [...old.paymentTypes, clean] : old.paymentTypes })); } catch (e) { Alert.alert('Could not add option', e instanceof Error ? e.message : 'Please try again.'); throw e; } };
  const toggleTheme = () => { const next: ThemeMode = themeMode === 'light' ? 'dark' : 'light'; setThemeMode(next); AsyncStorage.setItem(THEME_STORAGE_KEY, next).catch(() => {}); };
  const exportLedger = async (mode: 'party' | 'all') => { const groups: LedgerPdfGroup[] = mode === 'party' ? (selectedParty ? [{ party: selectedParty, rows: ledger, overallRows: ledger }] : []) : Object.values(records.reduce((all, record) => { const party = String(record.values.party || 'Unassigned'); (all[party] ||= []).push(record); return all; }, {} as Record<string, PurchaseRecord[]>)).map((rows) => ({ party: String(rows[0]?.values.party || 'Unassigned'), rows, overallRows: rows })); if (!groups.length || groups.every((group) => !group.rows.length)) { Alert.alert('No ledger data', 'Select a party with entries before downloading its ledger.'); return; } setExporting(mode); try { const html = ledgerPdfHtml(groups); if (Platform.OS === 'web') { const reportWindow = window.open('', '_blank'); if (!reportWindow) throw new Error('Please allow pop-ups to download the PDF.'); reportWindow.document.open(); reportWindow.document.write(html); reportWindow.document.close(); reportWindow.focus(); setTimeout(() => reportWindow.print(), 350); Alert.alert('Save your PDF', 'The printable statement opened in a new tab. Choose “Save as PDF”.'); } else { await Print.printAsync({ html }); Alert.alert('Ready to save', 'Choose “Save as PDF” in the system print dialog.'); } } catch (e) { Alert.alert('Could not create PDF', e instanceof Error ? e.message : 'Please try again.'); } finally { setExporting(null); } }; const exportLedgerForRows = async (rows: PurchaseRecord[], period: string) => { if (!selectedParty || !rows.length) { Alert.alert('No ledger data', 'Choose a date with entries before downloading the ledger.'); return; } setExporting('party'); try { const html = ledgerPdfHtml([{ party: selectedParty, rows, overallRows: ledger, period }]); if (Platform.OS === 'web') { const reportWindow = window.open('', '_blank'); if (!reportWindow) throw new Error('Please allow pop-ups to download the PDF.'); reportWindow.document.open(); reportWindow.document.write(html); reportWindow.document.close(); reportWindow.focus(); setTimeout(() => reportWindow.print(), 350); Alert.alert('Save your PDF', 'The printable statement opened in a new tab. Choose “Save as PDF”.'); } else { await Print.printAsync({ html }); Alert.alert('Ready to save', 'Choose “Save as PDF” in the system print dialog.'); } } catch (e) { Alert.alert('Could not create PDF', e instanceof Error ? e.message : 'Please try again.'); } finally { setExporting(null); } };
